import java.util.*;
class Deadlocks {record Request(String tx,String key,String mode){}record Edge(String from,String to){}
static Set<String> blockers(Request r,Map<String,Map<String,String>>holders,List<Request>earlier){String own=holders.getOrDefault(r.key(),Map.of()).get(r.tx());if("X".equals(own)||("S".equals(own)&&r.mode().equals("S")))return Set.of();Set<String>out=new HashSet<>();holders.getOrDefault(r.key(),Map.of()).forEach((owner,mode)->{if(!owner.equals(r.tx())&&(r.mode().equals("X")||mode.equals("X")))out.add(owner);});for(Request p:earlier)if(p.key().equals(r.key())&&!p.tx().equals(r.tx())&&(r.mode().equals("X")||p.mode().equals("X")))out.add(p.tx());return out;}
static List<Edge> graph(Map<String,Map<String,String>>holders,List<Request>queue){List<Edge>out=new ArrayList<>();for(int i=0;i<queue.size();i++)for(String to:blockers(queue.get(i),holders,queue.subList(0,i)))out.add(new Edge(queue.get(i).tx(),to));return out;}
static String visit(String n,List<Edge>edges,List<String>active,Set<String>done){int index=active.indexOf(n);if(index>=0)return Collections.max(active.subList(index,active.size()));if(done.contains(n))return null;active.add(n);for(Edge e:edges)if(e.from().equals(n)){String found=visit(e.to(),edges,active,done);if(found!=null)return found;}active.remove(active.size()-1);done.add(n);return null;}
static String victim(List<Edge>edges){List<String>active=new ArrayList<>();Set<String>done=new HashSet<>();for(String n:List.of("A","B","C")){String found=visit(n,edges,active,done);if(found!=null)return found;}return null;}}
